query:
for $f in /Derivatemeldung/InvestmentFonds
let $limit := if ($f/Berechnungsmethode = 'Comm') then 100 else if ($f/Berechnungsmethode = 'aVaR') then 20 else 200
let $value := xs:decimal(($f/MaxRisikoangabe[normalize-space()], $f/Risikoangabe)[1])
order by $value div $limit descending
return string-join(($f/ISIN, $f/FondsName, $f/Berechnungsmethode, format-number($value * 100 div $limit, '0.0') || ' %'), ' | ')

for $r in /AIFReportingInfo/AIFRecordInfo
let $d := $r/AIFCompleteDescription/AIFPrincipalInfo
return string-join(($r/AIFNationalCode, $r/AIFName, $d/AIFDescription/PredominantAIFType, $d/AIFDescription/AIFBaseCurrencyDescription/AIFNetAssetValue ! format-number(xs:decimal(.), '#,##0'), $r/ReportingPeriodType || ' ' || $r/ReportingPeriodYear), ' | ')

for $r in /AIFReportingInfo/AIFRecordInfo
let $p := $r/AIFCompleteDescription/AIFPrincipalInfo
return string-join(($r/AIFNationalCode, 'NAV ' || sum($p/NAVGeographicalFocus/*[normalize-space()] ! xs:decimal(.)), 'AuM ' || sum($p/AUMGeographicalFocus/*[normalize-space()] ! xs:decimal(.))), ' | ')
